'use strict';
Object.assign(labels,{friends:['BETTER TOGETHER','Your world. Your people.']});
let multiplayerTimer=null,lastPlayitState={};
function multiplayerForm(title,fields,submit){const dialog=document.createElement('dialog');dialog.className='wide-dialog';const form=document.createElement('form');form.method='dialog';const heading=document.createElement('h2');heading.textContent=title;form.append(heading);for(const field of fields){const label=document.createElement('label');label.style.cssText='display:block;margin:16px 0';label.append(document.createTextNode(field.label));let input;if(field.options){input=document.createElement('select');for(const [value,text]of field.options){const option=new Option(text,value);input.add(option);}}else{input=document.createElement('input');input.type=field.type||'text';input.maxLength=field.max||2048;input.value=field.value||'';input.placeholder=field.placeholder||'';}input.name=field.name;if(field.type==='checkbox')input.required=true;label.append(input);form.append(label);}const note=document.createElement('p');note.className='muted';note.textContent='Minecraft server EULA: https://www.minecraft.net/eula. Hosting uses a separate vanilla world; mods on your client do not turn this into a modded server.';if(fields.some(f=>f.name==='acceptEula'))form.append(note);const error=document.createElement('p');error.setAttribute('role','alert');form.append(error);const controls=document.createElement('div');controls.className='settings-actions';const cancel=document.createElement('button');cancel.type='button';cancel.className='button subtle';cancel.textContent='Cancel';cancel.onclick=()=>dialog.close();const save=document.createElement('button');save.type='submit';save.className='button primary';save.textContent='Save';controls.append(cancel,save);form.append(controls);form.onsubmit=async event=>{event.preventDefault();save.disabled=true;try{const value=Object.fromEntries(new FormData(form));value.acceptEula=form.elements.acceptEula?.checked===true;await submit(value);dialog.close();await loadMultiplayer();}catch(e){error.textContent=e.message;}finally{save.disabled=false;}};dialog.append(form);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();}
async function loadMultiplayer(){const data=await api('multiplayer-state');lastPlayitState=data.playit||{};$('playit-status').textContent=(lastPlayitState.status||'Start a server, then Share with Playit.')+(lastPlayitState.address?' Public address: '+lastPlayitState.address:'');$('playit-stop').disabled=!lastPlayitState.running;const games=state.instances.filter(x=>['26.3','1.21.11','1.21.1','1.20.1'].includes(x.minecraft));$('friends-grid').innerHTML=data.friends.length?data.friends.map(f=>'<article class="content-card"><span class="sponsor-badge">'+escape(f.kind==='address'?'SAVED SERVER':'FRIEND INVITE')+' · '+escape(f.minecraft)+'</span><h3>'+escape(f.name)+'</h3><p>'+escape(f.address||'The host must keep its Playit agent and server running.')+'</p><div class="settings-actions"><button class="button primary" data-friend-join="'+escape(f.id)+'">Join with selected instance</button><button class="button tiny" data-friend-remove="'+escape(f.id)+'">Remove</button></div></article>').join(''):empty('Bring your people.','Save a friend’s Playit code for one-click joining. For Aternos, save its server address and start it from the official panel.');$('hosting-grid').innerHTML=data.servers.length?data.servers.map(s=>'<article class="content-card"><span class="sponsor-badge">'+escape(s.minecraft)+' · OFFLINE IDENTITIES</span><h3>'+escape(s.name)+'</h3><p>'+s.memory+' MB · '+(s.running?'Running':'Stopped')+(s.sharing?' · Sharing':'')+'</p><div class="settings-actions"><button class="button primary" data-server-start="'+escape(s.id)+'" '+(s.running?'disabled':'')+'>Start</button><button class="button subtle" data-server-stop="'+escape(s.id)+'" '+(!s.running?'disabled':'')+'>Save & stop</button><button class="button subtle" data-server-console="'+escape(s.id)+'" '+(!s.running?'disabled':'')+'>Console</button><button class="button subtle" data-server-share="'+escape(s.id)+'" '+(!s.running?'disabled':'')+'>Share with Playit</button><button class="button tiny" data-server-unshare="'+escape(s.id)+'" '+(!s.sharing?'disabled':'')+'>Stop sharing</button></div></article>').join(''):empty('A place to meet.','Create an isolated vanilla server from one of your installed game versions.');const bind=(key,fn)=>document.querySelectorAll('[data-'+key+']').forEach(b=>b.onclick=()=>action(()=>fn(b.getAttribute('data-'+key))));bind('friend-remove',async id=>{await api('friend-save',{id,remove:true});await loadMultiplayer();});bind('friend-join',async id=>{if(!selected())throw Error('Select a matching instance from Play first.');await api('friend-join',{id,instanceId:selectedId,offline:$('offline').checked,username:$('offline-name').value||state.settings.offlineName});await refresh();toast('Connecting to your friend. Keep the launcher open.');});for(const key of ['start','stop','unshare'])bind('server-'+key,async id=>{await api('server-'+key,{id});await loadMultiplayer();});bind('server-console',openServerConsole);bind('server-share',async id=>{const result=await api('server-share',{id});if(result.pending){toast(result.claim?'Link your Playit account to enable the free tunnel.':result.status||'Playit is starting. Use Link / manage Playit account when ready.');if(result.claim)await api('playit-open',{url:result.claim});await loadMultiplayer();return;}const dialog=document.createElement('dialog');const heading=document.createElement('h2');heading.textContent='Your Playit friend code';const note=document.createElement('p');note.textContent='Share this code with your friend. It contains a public Playit address they can save for one-click joining on Windows or Android. The server and host agent must stay running.';const input=document.createElement('textarea');input.value=result.invite;input.readOnly=true;input.rows=5;input.style.width='100%';const close=document.createElement('button');close.textContent='Done';close.className='button primary';close.onclick=()=>dialog.close();dialog.append(heading,note,input,close);dialog.onclose=()=>dialog.remove();document.body.append(dialog);dialog.showModal();input.select();await loadMultiplayer();});}
async function openServerConsole(id){const dialog=document.createElement('dialog');dialog.className='wide-dialog';const title=document.createElement('h2');title.textContent='Server console';const log=document.createElement('pre');log.style.cssText='max-height:45vh;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere';const form=document.createElement('form');const input=document.createElement('input');input.placeholder='Command, for example list or say Hello';input.maxLength=1024;input.setAttribute('aria-label','Server console command');const send=document.createElement('button');send.textContent='Send';send.className='button primary';form.append(input,send);form.onsubmit=event=>{event.preventDefault();action(async()=>{await api('server-console',{id,command:input.value});input.value='';await poll();});};const close=document.createElement('button');close.className='button subtle';close.textContent='Close console';close.onclick=()=>dialog.close();dialog.append(title,log,form,close);let timer;const poll=async()=>{try{const state=await api('server-console',{id});log.textContent=state.lines.join('\n');log.scrollTop=log.scrollHeight;title.textContent=state.ready?'Server console · ready':'Server console · starting';}catch(e){log.textContent=e.message;}};dialog.onclose=()=>{clearInterval(timer);dialog.remove();};document.body.append(dialog);dialog.showModal();await poll();timer=setInterval(poll,2000);}
$('friends-add').onclick=()=>multiplayerForm('Add a Playit friend code',[{name:'name',label:'Friend name',max:60},{name:'invite',label:'Invite code',placeholder:'bora2.…'}],p=>api('friend-save',p));
$('friends-address').onclick=()=>multiplayerForm('Save an Aternos or Minecraft server',[{name:'name',label:'Server name',max:60},{name:'address',label:'Address',placeholder:'your-server.aternos.me:25565'},{name:'minecraft',label:'Minecraft version',options:['26.3','1.21.11','1.21.1','1.20.1'].map(v=>[v,v])}],p=>api('friend-save',p));
$('host-create').onclick=()=>{const installed=state.instances.filter(i=>i.installedVersion&&['26.3','1.21.11','1.21.1','1.20.1'].includes(i.minecraft));if(!installed.length)return toast('Install a supported instance first to prepare its Java runtime.',true);multiplayerForm('Create your friends server',[{name:'name',label:'World/server name',max:60,value:'Our Boralances world'},{name:'instanceId',label:'Installed Java/game version',options:installed.map(i=>[i.id,i.name+' · '+i.minecraft])},{name:'memory',label:'Server RAM in MB',type:'number',value:'2048'},{name:'acceptEula',label:'I have read and accept the Minecraft EULA for this server.',type:'checkbox'}],p=>api('server-create',{...p,minecraft:installed.find(i=>i.id===p.instanceId).minecraft,memory:Number(p.memory)}));};
$('friends-refresh').onclick=()=>action(loadMultiplayer);$('playit-link').onclick=()=>action(()=>api('playit-open',{url:lastPlayitState.claim}));$('playit-stop').onclick=()=>action(async()=>{await api('playit-stop');await loadMultiplayer();});$('aternos-panel').onclick=()=>action(()=>api('aternos-open'));window.launcher.on('server-event',event=>{if(event.error)toast(event.error,true);else if(event.status)toast(event.status);if(page==='friends')action(loadMultiplayer);});
